#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <random>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace nvcuda;
#define CUDA_CHECK(x) do { cudaError_t e=(x); if(e!=cudaSuccess){std::ostringstream s;s<<cudaGetErrorString(e);throw std::runtime_error(s.str());} } while(0)
struct Shape{int m,k,n;}; constexpr std::uint32_t GUARD=0x7fc12345;
std::vector<float> make(std::size_t n,unsigned seed){std::mt19937 g(seed);std::uniform_real_distribution<float>d(-1,1);std::vector<float>v(n);for(float&x:v)x=d(g);return v;}
void cpu(const std::vector<float>&a,const std::vector<float>&b,std::vector<float>&c,Shape s){std::fill(c.begin(),c.end(),0);for(int r=0;r<s.m;r++)for(int k=0;k<s.k;k++){float av=a[(std::size_t)r*s.k+k];for(int n=0;n<s.n;n++)c[(std::size_t)r*s.n+n]+=av*b[(std::size_t)k*s.n+n];}}
__global__ void wmma(const half*a,const half*b,float*c,int K,int N){int tm=blockIdx.y,tn=blockIdx.x;wmma::fragment<wmma::accumulator,16,16,16,float> acc;wmma::fill_fragment(acc,0.0f);for(int kt=0;kt<K;kt+=16){wmma::fragment<wmma::matrix_a,16,16,16,half,wmma::row_major> af;wmma::fragment<wmma::matrix_b,16,16,16,half,wmma::col_major> bf;wmma::load_matrix_sync(af,a+(tm*16)*K+kt,K);wmma::load_matrix_sync(bf,b+(tn*16)*K+kt,K);wmma::mma_sync(acc,af,bf,acc);}wmma::store_matrix_sync(c+(tm*16)*N+tn*16,acc,N,wmma::mem_row_major);}
struct Stats{double abs=0,rel=0,rmse=0,scale=0;};
Stats diff(const std::vector<float>&a,const std::vector<float>&b){Stats s;double q=0;for(std::size_t i=0;i<a.size();i++){double d=std::abs((double)a[i]-b[i]);s.abs=std::max(s.abs,d);s.scale=std::max(s.scale,std::abs((double)a[i]));s.rel=std::max(s.rel,d/std::max(std::abs((double)a[i]),1e-12));q+=d*d;}s.rmse=std::sqrt(q/a.size());return s;}
int main(int argc,char**argv){try{std::string outPath=argc>1?argv[1]:"wmma_dual.csv";std::ofstream out(outPath);out<<"M,K,N,version,input_precision,accumulator_precision,output_precision,max_abs_error_vs_fp16_ref,max_rel_error_vs_fp16_ref,rmse_vs_fp16_ref,max_abs_error_vs_fp32_ref,max_rel_error_vs_fp32_ref,rmse_vs_fp32_ref,max_abs_fp16_reference,max_abs_fp32_reference,canary_status,cuda_allocation_status,cuda_copy_status,cuda_launch_status,cuda_sync_status,implementation_correctness,precision_impact_status\n";Shape shapes[]={{16,16,16},{32,32,32},{64,48,80},{128,128,128},{256,256,256},{512,384,640},{512,512,512},{1024,1024,1024}};for(Shape s:shapes){auto a=make((std::size_t)s.m*s.k,100+s.m),b=make((std::size_t)s.k*s.n,200+s.n);std::vector<half>ha(a.size()),hb((std::size_t)s.n*s.k);for(std::size_t i=0;i<a.size();i++)ha[i]=__float2half(a[i]);for(int k=0;k<s.k;k++)for(int n=0;n<s.n;n++)hb[(std::size_t)n*s.k+k]=__float2half(b[(std::size_t)k*s.n+n]);std::vector<float>fp32((std::size_t)s.m*s.n),fp16((std::size_t)s.m*s.n),got(fp32.size()),aq(a.size()),bq(b.size());for(std::size_t i=0;i<aq.size();i++)aq[i]=__half2float(ha[i]);for(int k=0;k<s.k;k++)for(int n=0;n<s.n;n++)bq[(std::size_t)k*s.n+n]=__half2float(hb[(std::size_t)n*s.k+k]);cpu(a,b,fp32,s);cpu(aq,bq,fp16,s);half *da=nullptr,*db=nullptr;float*dc=nullptr;bool canary=true;std::vector<std::uint32_t> guard(fp32.size()+32,GUARD);CUDA_CHECK(cudaMalloc((void**)&da,ha.size()*sizeof(half)));CUDA_CHECK(cudaMalloc((void**)&db,hb.size()*sizeof(half)));CUDA_CHECK(cudaMalloc((void**)&dc,(fp32.size()+32)*sizeof(float)));CUDA_CHECK(cudaMemcpy(da,ha.data(),ha.size()*sizeof(half),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(db,hb.data(),hb.size()*sizeof(half),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(dc,guard.data(),guard.size()*sizeof(std::uint32_t),cudaMemcpyHostToDevice));wmma<<<dim3((s.n+15)/16,(s.m+15)/16),32>>>(da,db,dc+16,s.k,s.n);CUDA_CHECK(cudaPeekAtLastError());CUDA_CHECK(cudaDeviceSynchronize());CUDA_CHECK(cudaMemcpy(got.data(),dc+16,got.size()*sizeof(float),cudaMemcpyDeviceToHost));CUDA_CHECK(cudaMemcpy(guard.data(),dc,guard.size()*sizeof(std::uint32_t),cudaMemcpyDeviceToHost));for(int i=0;i<16;i++)if(guard[i]!=GUARD||guard[16+got.size()+i]!=GUARD)canary=false;auto x=diff(fp16,got);auto y=diff(fp32,got);double ma=0,mb=0;for(float z:fp16)ma=std::max(ma,std::abs((double)z));for(float z:fp32)mb=std::max(mb,std::abs((double)z));double impl_tol=1e-3+1e-4*ma;bool impl_pass=x.abs<=impl_tol;out<<s.m<<','<<s.k<<','<<s.n<<",V3-WMMA-FP16,FP16,FP32,FP32,"<<std::setprecision(12)<<x.abs<<','<<x.rel<<','<<x.rmse<<','<<y.abs<<','<<y.rel<<','<<y.rmse<<','<<ma<<','<<mb<<','<<(canary?"PASS":"FAIL")<<",PASS,PASS,PASS,PASS,"<<(impl_pass?"PASS":"FAIL")<<",MEASURED\n";cudaFree(da);cudaFree(db);cudaFree(dc);}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
